// Put the MediaPipe runtime where the operator studio loads it from.
//
// The studio's segmentation needs two things at `/mediapipe/`:
//   * the WASM fileset (`FilesetResolver.forVisionTasks('/mediapipe/wasm')`)
//   * the selfie-segmenter model (`/mediapipe/selfie_segmenter_landscape.tflite`)
//
// They are NOT committed: the wasm alone is ~41 MB, and a repo that carries
// binary runtimes for one operator-only page is the wrong trade. `public/mediapipe`
// is gitignored and regenerated by `npm run build` (this script runs BEFORE
// `vite build`, because Vite copies `public/` at build start).
//
// Idempotent: a file whose size already matches is left alone, so a rebuild is
// cheap and offline. The model download is cached in `node_modules/.cache` so a
// rebuild after `npm ci` re-downloads once, not once per build.
//
// Importable without running: `main()` is guarded (AGENTS.md).

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/** Where the studio asks for the runtime from. */
export const DEFAULT_OUT_DIR = path.join(REPO_ROOT, 'public', 'mediapipe');

/** The package that ships the wasm fileset. */
export const WASM_SOURCE_DIR = path.join(
    REPO_ROOT, 'node_modules', '@mediapipe', 'tasks-vision', 'wasm'
);

/** The model the adapter runs (see src/modules/looks/segmentation.web.js). */
export const MODEL_FILE = 'selfie_segmenter_landscape.tflite';
export const MODEL_URL =
    'https://storage.googleapis.com/mediapipe-models/image_segmenter/'
    + 'selfie_segmenter_landscape/float16/1/selfie_segmenter_landscape.tflite';

/** Download cache, so a clean `npm ci` does not re-fetch on every build. */
export const CACHE_DIR = path.join(REPO_ROOT, 'node_modules', '.cache', 'mediapipe');

function sizeOf(file) {
    try {
        return fs.statSync(file).size;
    } catch (e) {
        return -1;
    }
}

/**
 * Copy one file when it is missing or a different size.
 *
 * @returns {'copied'|'current'|'missing-source'}
 */
export function syncFile(sourcePath, targetPath) {
    const sourceSize = sizeOf(sourcePath);
    if (sourceSize < 0) return 'missing-source';
    if (sizeOf(targetPath) === sourceSize) return 'current';
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.copyFileSync(sourcePath, targetPath);
    return 'copied';
}

/**
 * Sync the wasm fileset into `outDir/wasm`.
 *
 * @returns {{ copied: string[], current: string[], missing: string[] }}
 */
export function syncWasm({ sourceDir = WASM_SOURCE_DIR, outDir = DEFAULT_OUT_DIR } = {}) {
    const result = { copied: [], current: [], missing: [] };
    let entries;
    try {
        entries = fs.readdirSync(sourceDir);
    } catch (e) {
        result.missing.push(sourceDir);
        return result;
    }
    for (const entry of entries) {
        const outcome = syncFile(path.join(sourceDir, entry), path.join(outDir, 'wasm', entry));
        if (outcome === 'copied') result.copied.push(entry);
        else if (outcome === 'current') result.current.push(entry);
        else result.missing.push(entry);
    }
    return result;
}

/**
 * Make the model available, downloading it only when there is no cached copy.
 *
 * @param {{ outDir?: string, cacheDir?: string, fetchImpl?: Function }} [options]
 * @returns {Promise<'copied'|'current'|'downloaded'|'unavailable'>}
 */
export async function syncModel({
    outDir = DEFAULT_OUT_DIR,
    cacheDir = CACHE_DIR,
    fetchImpl = typeof fetch === 'function' ? fetch : null,
} = {}) {
    const target = path.join(outDir, MODEL_FILE);
    const cached = path.join(cacheDir, MODEL_FILE);
    if (sizeOf(target) > 0 && sizeOf(target) === sizeOf(cached)) return 'current';
    if (sizeOf(target) > 0 && sizeOf(cached) < 0) {
        // Already staged but no cache copy: keep it and seed the cache so the
        // next build does not reach the network at all.
        fs.mkdirSync(cacheDir, { recursive: true });
        fs.copyFileSync(target, cached);
        return 'current';
    }
    if (sizeOf(cached) > 0) {
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.copyFileSync(cached, target);
        return 'copied';
    }
    if (!fetchImpl) return 'unavailable';
    try {
        const response = await fetchImpl(MODEL_URL);
        if (!response || !response.ok) {
            console.warn(`[mediapipe] model download failed (${response && response.status})`);
            return 'unavailable';
        }
        const bytes = Buffer.from(await response.arrayBuffer());
        if (bytes.length === 0) return 'unavailable';
        fs.mkdirSync(cacheDir, { recursive: true });
        fs.writeFileSync(cached, bytes);
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.writeFileSync(target, bytes);
        return 'downloaded';
    } catch (e) {
        console.warn(`[mediapipe] model download failed: ${e.message}`);
        return 'unavailable';
    }
}

async function main() {
    const outDir = process.env.MEDIAPIPE_OUT_DIR || DEFAULT_OUT_DIR;
    const wasm = syncWasm({ outDir });
    const model = await syncModel({ outDir });
    console.log(
        `[mediapipe] wasm: ${wasm.copied.length} copied, ${wasm.current.length} current`
        + ` → ${path.relative(REPO_ROOT, outDir)}/wasm`
    );
    if (wasm.missing.length > 0) {
        console.error(
            `[mediapipe] missing wasm files (is @mediapipe/tasks-vision installed?): ${wasm.missing.join(', ')}`
        );
        process.exitCode = 1;
        return 1;
    }
    console.log(`[mediapipe] model ${MODEL_FILE}: ${model}`);
    if (model === 'unavailable') {
        // Not fatal: the studio degrades to recording the raw camera, and a take
        // without the effect is still a usable take. Say so loudly.
        console.warn('[mediapipe] the model is missing — the studio will record the raw camera');
    }
    return 0;
}

const invokedDirectly = process.argv[1]
    && import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) {
    main().catch((e) => {
        console.error('ERROR:', e.message);
        process.exit(1);
    });
}
